/**
 * Seed LLM Providers catalog
 */
async function seedLlmProviders(prisma: PrismaClient): Promise<void> {
  console.log('🤖 Seeding LLM Providers...');

  const auditFields = {
    createdAt_: new Date(),
    version_: '0',
    createdBy_: { connect: { id: 'SYSADMIN' } },
  };

  for (const provider of LLM_PROVIDERS) {
    try {
      await prisma.llmProvider.upsert({
        where: { code: provider.code },
        update: {
          name: provider.name,
          requiresApiKey: provider.requiresApiKey,
          requiresBaseUrl: provider.requiresBaseUrl,
          defaultModels: provider.defaultModels,
        },
        create: {
          code: provider.code,
          name: provider.name,
          requiresApiKey: provider.requiresApiKey,
          requiresBaseUrl: provider.requiresBaseUrl,
          defaultModels: provider.defaultModels,
          ...auditFields,
        },
      });
    } catch (error) {
      console.error(`Failed to seed LLM provider ${provider.code}:`, error);
    }
  }

  console.log(`✅ Seeded ${LLM_PROVIDERS.length} LLM providers`);
}

/**
 * Seed default TenantLlmConfig for AGILMIND tenant (local development)
 */
async function seedTenantLlmConfig(prisma: PrismaClient): Promise<void> {
  console.log('⚙️  Seeding Tenant LLM Config...');

  // Find AGILMIND tenant
  const tenant = await prisma.tenant.findUnique({ where: { id: 'AGILMIND' } });
  if (!tenant) {
    console.log('   ⚠️  AGILMIND tenant not found, skipping TenantLlmConfig');
    return;
  }

  // Find Ollama provider
  const provider = await prisma.llmProvider.findUnique({ where: { code: 'ollama' } });
  if (!provider) {
    console.log('   ⚠️  Ollama provider not found, skipping TenantLlmConfig');
    return;
  }

  // Check if config already exists
  const existing = await prisma.tenantLlmConfig.findFirst({
    where: { tenant_id_: tenant.id },
  });

  if (existing) {
    console.log('   ℹ️  TenantLlmConfig already exists for AGILMIND');
    return;
  }

  // Create config
  await prisma.tenantLlmConfig.create({
    data: {
      tenant_: { connect: { id: tenant.id } },
      provider: { connect: { id: provider.id } },
      model: 'qwen3:4b',
      baseUrl: 'http://localhost:11434/v1',
      enabled: true,
      createdAt_: new Date(),
      version_: '0',
      createdBy_: { connect: { id: 'SYSADMIN' } },
    },
  });

  console.log('✅ Created TenantLlmConfig for AGILMIND (Ollama qwen3:4b)');
}

/**
 * Seed AI Search Patterns
 * These patterns are global (sharedAcrossTenants) and improve LLM accuracy
 */
async function seedAiSearchPatterns(prisma: PrismaClient): Promise<void> {
  // Check if AiSearchPattern entity exists (may not exist in older projects)
  const modelExists = !!(prisma as any).aiSearchPattern;
  if (!modelExists) {
    console.log('   ⚠️  AiSearchPattern entity not found, skipping patterns seed');
    return;
  }

  console.log('🧠 Seeding AI Search Patterns...');

  const auditFields = {
    createdAt_: new Date(),
    version_: '0',
    createdBy_: { connect: { id: 'SYSADMIN' } },
  };

  for (const pattern of AI_SEARCH_PATTERNS) {
    try {
      await (prisma as any).aiSearchPattern.upsert({
        where: { name: pattern.name },
        update: {
          description: pattern.description,
          pattern: pattern.pattern,
          pathTypes: pattern.pathTypes,
          tools: pattern.tools,
          priority: pattern.priority,
          proposedBy: pattern.proposedBy,
        },
        create: {
          name: pattern.name,
          description: pattern.description,
          pattern: pattern.pattern,
          pathTypes: pattern.pathTypes,
          tools: pattern.tools,
          priority: pattern.priority,
          proposedBy: pattern.proposedBy,
          active: true,
          evaluationCount: 0,
          successCount: 0,
          ...auditFields,
        },
      });
    } catch (error) {
      console.error(`Failed to seed AI Search pattern ${pattern.name}:`, error);
    }
  }

  console.log(`✅ Seeded ${AI_SEARCH_PATTERNS.length} AI Search patterns`);
}

/**
 * Main seed function for AI Search module
 */
export async function seedAiSearch(prisma: PrismaClient): Promise<void> {
  console.log('🔍 Seeding AI Search catalogs...');

  await seedLlmProviders(prisma);
  await seedTenantLlmConfig(prisma);
  await seedAiSearchPatterns(prisma);

  console.log('✅ AI Search seed complete');
}
